 if ( ! defined( 'ABSPATH' ) ) { exit; } use ElementorPro\Modules\DisplayConditions\Conditions\Base\Condition_Base; use ElementorPro\Modules\DisplayConditions\Classes\Comparator_Provider; use Elementor\Controls_Manager; class HVM_Mixer_Field_Condition extends Condition_Base { public function get_name() { return 'hvm_mixer_field'; } public function get_group() { return 'hvm_mixer'; } public function get_label() { return esc_html__( 'Mixer Field', 'hivemind-mixer' ); } private function field_options() { $opts = array(); if ( function_exists( 'hvm_flat_fields' ) ) { foreach ( hvm_flat_fields() as $key => $f ) { $type = isset( $f['type'] ) ? $f['type'] : 'text'; $label = isset( $f['label'] ) ? $f['label'] : $key; if ( 'gallery' === $type ) { $label .= ' (gallery)'; } elseif ( 'repeater' === $type ) { $label .= ' (list)'; } $opts[ $key ] = $label; } } return $opts; } public function get_options() { $this->add_control( 'hvm_field', array( 'type' => Controls_Manager::SELECT, 'options' => $this->field_options(), 'default' => '', 'label_block' => true, 'required' => true, ) ); $comparators = Comparator_Provider::get_comparators( array( Comparator_Provider::COMPARATOR_IS, Comparator_Provider::COMPARATOR_IS_NOT, Comparator_Provider::COMPARATOR_CONTAINS, Comparator_Provider::COMPARATOR_NOT_CONTAIN, Comparator_Provider::COMPARATOR_IS_EMPTY, Comparator_Provider::COMPARATOR_IS_NOT_EMPTY, ) ); $this->add_control( 'comparator', array( 'type' => Controls_Manager::SELECT, 'options' => $comparators, 'default' => Comparator_Provider::COMPARATOR_IS, ) ); $this->add_control( 'hvm_value', array( 'type' => Controls_Manager::TEXT, 'label_block' => true, 'placeholder' => esc_html__( 'Value', 'hivemind-mixer' ), 'condition' => array( 'comparator!' => array( Comparator_Provider::COMPARATOR_IS_EMPTY, Comparator_Provider::COMPARATOR_IS_NOT_EMPTY, ), ), ) ); } public function check( $args ) : bool { $field = isset( $args['hvm_field'] ) ? (string) $args['hvm_field'] : ''; $comparator = isset( $args['comparator'] ) ? (string) $args['comparator'] : Comparator_Provider::COMPARATOR_IS; $value = isset( $args['hvm_value'] ) ? (string) $args['hvm_value'] : ''; if ( '' === $field ) { return true; } $post_id = function_exists( 'hvm_post_id' ) ? hvm_post_id() : get_queried_object_id(); $meta = $post_id ? get_post_meta( $post_id, '_hvm_' . $field, true ) : ''; if ( is_array( $meta ) ) { $flat = array(); array_walk_recursive( $meta, function ( $v ) use ( &$flat ) { if ( is_scalar( $v ) && '' !== (string) $v ) { $flat[] = (string) $v; } } ); $meta = implode( ',', $flat ); } $meta = trim( (string) $meta ); switch ( $comparator ) { case Comparator_Provider::COMPARATOR_IS_EMPTY: return '' === $meta; case Comparator_Provider::COMPARATOR_IS_NOT_EMPTY: return '' !== $meta; case Comparator_Provider::COMPARATOR_IS_NOT: return $meta !== $value; case Comparator_Provider::COMPARATOR_CONTAINS: return '' !== $value && false !== stripos( $meta, $value ); case Comparator_Provider::COMPARATOR_NOT_CONTAIN: return '' === $value || false === stripos( $meta, $value ); case Comparator_Provider::COMPARATOR_IS: default: return $meta === $value; } } } class HVM_Mixer_Available_Condition extends Condition_Base { public function get_name() { return 'hvm_is_available'; } public function get_group() { return 'hvm_mixer'; } public function get_label() { return esc_html__( 'Is Available', 'hivemind-mixer' ); } public function get_options() { $this->add_control( 'hvm_state', array( 'type' => Controls_Manager::SELECT, 'default' => 'available', 'label_block' => true, 'options' => array( 'available' => esc_html__( 'Available (upcoming / ongoing)', 'hivemind-mixer' ), 'ended' => esc_html__( 'Ended', 'hivemind-mixer' ), ), ) ); } public function check( $args ) : bool { $state = isset( $args['hvm_state'] ) ? (string) $args['hvm_state'] : 'available'; $avail = $this->is_available(); return ( 'ended' === $state ) ? ! $avail : $avail; } private function is_available() : bool { $post_id = function_exists( 'hvm_p